import { Icon } from "@iconify/react/dist/iconify.js";
import { useState, useRef, useEffect } from "react";

const ApproveResellerModal = ({ isOpen, onClose, reseller, onApprove, loading }) => {
  const [formData, setFormData] = useState({
    wallet_balance: "",
    grace_period_days: "",
    virtual_numbers_count: "3",
    price_per_number: "",
    validity_date: "",
    reference: "",
  });
  const [error, setError] = useState("");
  const isSubmittingRef = useRef(false);

  // Reset submitting flag when modal closes and set default validity date
  useEffect(() => {
    if (!isOpen) {
      isSubmittingRef.current = false;
      // Reset form when modal closes
      setFormData({
        wallet_balance: "",
        grace_period_days: "",
        virtual_numbers_count: "3",
        price_per_number: "",
        validity_date: "",
        reference: "",
      });
    } else {
      // When modal opens, set default validity date to 360 days from today
      const today = new Date();
      const validityDate = new Date(today);
      validityDate.setDate(today.getDate() + 360);
      const formattedDate = validityDate.toISOString().split('T')[0];
      
      setFormData(prev => ({
        ...prev,
        validity_date: formattedDate,
      }));
    }
  }, [isOpen]);

  // Reset submitting flag when loading completes (after a delay to ensure state is updated)
  useEffect(() => {
    if (!loading && isSubmittingRef.current) {
      // Small delay to ensure the parent component has finished processing
      const timer = setTimeout(() => {
        isSubmittingRef.current = false;
      }, 100);
      return () => clearTimeout(timer);
    }
  }, [loading]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
    setError("");
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    e.stopPropagation();
    
    // Prevent double submission - check multiple conditions
    if (loading || isSubmittingRef.current) {
      console.log("Submission blocked - already submitting", { loading, isSubmitting: isSubmittingRef.current });
      return;
    }
    
    setError("");

    // Validation
    if (!formData.wallet_balance || !formData.grace_period_days || !formData.virtual_numbers_count || !formData.price_per_number) {
      setError("Please fill all required fields");
      return;
    }

    const walletBalance = parseFloat(formData.wallet_balance);
    const gracePeriodDays = parseInt(formData.grace_period_days);
    const virtualNumbersCount = parseInt(formData.virtual_numbers_count);
    const pricePerNumber = parseFloat(formData.price_per_number);

    if (isNaN(walletBalance) || walletBalance < 0) {
      setError("Wallet balance must be a valid positive number");
      return;
    }

    if (isNaN(gracePeriodDays) || gracePeriodDays < 0) {
      setError("Grace period days must be a valid positive number");
      return;
    }

    if (isNaN(virtualNumbersCount) || virtualNumbersCount < 0) {
      setError("Virtual numbers count must be a valid positive number");
      return;
    }

    if (isNaN(pricePerNumber) || pricePerNumber < 0) {
      setError("Price per number must be a valid positive number");
      return;
    }

    // Set submitting flag IMMEDIATELY to prevent double submission
    isSubmittingRef.current = true;
    console.log("Starting approval submission", { walletBalance, gracePeriodDays, virtualNumbersCount, pricePerNumber });
    
    // Call onApprove - this should only happen once
    onApprove({
      wallet_balance: walletBalance,
      grace_period_days: gracePeriodDays,
      virtual_numbers_count: virtualNumbersCount,
      price_per_number: pricePerNumber,
      validity_date: formData.validity_date || null,
      reference: formData.reference || null,
    });
  };

  if (!isOpen) return null;

  return (
    <div className="modal show d-block" style={{ backgroundColor: 'rgba(0,0,0,0.5)' }} tabIndex="-1">
      <div className="modal-dialog modal-dialog-centered">
        <div className="modal-content radius-12">
          <div className="modal-header border-bottom">
            <h5 className="modal-title text-md text-primary-light">Approve Reseller</h5>
            <button
              type="button"
              className="btn-close"
              onClick={onClose}
              disabled={loading}
              aria-label="Close"
            />
          </div>
          <form onSubmit={handleSubmit} noValidate>
            <div className="modal-body p-24">
              <div className="mb-20">
                <p className="text-sm text-secondary-light mb-0">
                  Approve reseller: <strong>{reseller?.first_name} {reseller?.last_name}</strong> ({reseller?.email})
                </p>
              </div>

              {error && (
                <div className='alert alert-danger radius-8 mb-24' role='alert'>
                  <Icon icon='material-symbols:error-outline' className='icon me-2' />
                  {error}
                </div>
              )}

              <div className="mb-20">
                <label
                  htmlFor='wallet_balance'
                  className='form-label fw-semibold text-primary-light text-sm mb-8'
                >
                  Wallet Balance (₹) <span className='text-danger-600'>*</span>
                </label>
                <input
                  type='number'
                  step='0.01'
                  min='0'
                  className='form-control radius-8'
                  id='wallet_balance'
                  name='wallet_balance'
                  placeholder='Enter wallet balance'
                  value={formData.wallet_balance}
                  onChange={handleChange}
                  required
                  disabled={loading}
                />
              </div>

              <div className="mb-20">
                <label
                  htmlFor='grace_period_days'
                  className='form-label fw-semibold text-primary-light text-sm mb-8'
                >
                  Grace Period (Days) <span className='text-danger-600'>*</span>
                </label>
                <input
                  type='number'
                  min='0'
                  className='form-control radius-8'
                  id='grace_period_days'
                  name='grace_period_days'
                  placeholder='Enter grace period in days'
                  value={formData.grace_period_days}
                  onChange={handleChange}
                  required
                  disabled={loading}
                />
              </div>

              <div className="mb-20">
                <label
                  htmlFor='virtual_numbers_count'
                  className='form-label fw-semibold text-primary-light text-sm mb-8'
                >
                  Number of Virtual Numbers allowed for the customers <span className='text-danger-600'>*</span>
                </label>
                <input
                  type='number'
                  min='0'
                  className='form-control radius-8'
                  id='virtual_numbers_count'
                  name='virtual_numbers_count'
                  placeholder='Enter number of virtual numbers'
                  value={formData.virtual_numbers_count}
                  onChange={handleChange}
                  required
                  disabled={loading}
                />
              </div>

              <div className="mb-20">
                <label
                  htmlFor='price_per_number'
                  className='form-label fw-semibold text-primary-light text-sm mb-8'
                >
                  Price Per Number (₹) <span className='text-danger-600'>*</span>
                </label>
                <input
                  type='number'
                  step='0.01'
                  min='0'
                  className='form-control radius-8'
                  id='price_per_number'
                  name='price_per_number'
                  placeholder='Enter price per number'
                  value={formData.price_per_number}
                  onChange={handleChange}
                  required
                  disabled={loading}
                />
              </div>

              <div className="mb-20">
                <label
                  htmlFor='validity_date'
                  className='form-label fw-semibold text-primary-light text-sm mb-8'
                >
                  Validity Date (Optional)
                </label>
                <input
                  type='date'
                  className='form-control radius-8'
                  id='validity_date'
                  name='validity_date'
                  value={formData.validity_date}
                  onChange={handleChange}
                  disabled={loading}
                  min={new Date().toISOString().split('T')[0]}
                />
                <small className='text-xs text-secondary-light mt-4 d-block'>
                  Set the validity end date for the reseller. If not set, validity will be calculated based on wallet recharge.
                </small>
              </div>

              <div className="mb-20">
                <label
                  htmlFor='reference'
                  className='form-label fw-semibold text-primary-light text-sm mb-8'
                >
                  Reference
                </label>
                <input
                  type='text'
                  className='form-control radius-8'
                  id='reference'
                  name='reference'
                  placeholder='Enter reference (optional)'
                  value={formData.reference}
                  onChange={handleChange}
                  disabled={loading}
                />
              </div>
            </div>
            <div className="modal-footer border-top">
              <button
                type="button"
                className="btn btn-secondary radius-8"
                onClick={onClose}
                disabled={loading}
              >
                Cancel
              </button>
              <button
                type="submit"
                className="btn btn-primary radius-8"
                disabled={loading || isSubmittingRef.current}
                onClick={(e) => {
                  // Prevent any potential double-click issues
                  if (loading || isSubmittingRef.current) {
                    e.preventDefault();
                    e.stopPropagation();
                  }
                }}
              >
                {loading ? (
                  <>
                    <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                    Approving...
                  </>
                ) : (
                  "Approve Reseller"
                )}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default ApproveResellerModal;
