import { Icon } from "@iconify/react/dist/iconify.js";
import { useState, useEffect, useRef } from "react";
import { getMstSubscriptionPlans } from "@/hasura/mutations/subscriptionPlan";
import { getUserData, getAuthToken } from "@/utils/auth";
import { getApiBaseUrl } from "@/utils/apiUrl";

const AddVirtualNumberModal = ({ isOpen, onClose, customer, onSuccess }) => {
  const isSubmittingRef = useRef(false);

  const [formData, setFormData] = useState({
    payment_method: "",
    subscription_plan_id: "",
    payment_reference_number: "",
    payment_amount: "",
    payment_date: "",
    call_forwarding_number: "",
  });
  const [subscriptionPlans, setSubscriptionPlans] = useState([]);
  const [loadingPlans, setLoadingPlans] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState(false);

  useEffect(() => {
    if (isOpen && customer) {
      const today = new Date().toISOString().split("T")[0];
      setFormData({
        payment_method: "",
        subscription_plan_id: "",
        payment_reference_number: "",
        payment_amount: "",
        payment_date: today,
        call_forwarding_number: customer.phone || "",
      });
      setError("");
      setSuccess(false);
    }
  }, [isOpen, customer]);

  useEffect(() => {
    if (isOpen && (formData.payment_method === "online" || formData.payment_method === "offline")) {
      fetchSubscriptionPlans();
    }
  }, [isOpen, formData.payment_method]);

  const fetchSubscriptionPlans = async () => {
    setLoadingPlans(true);
    try {
      const userData = getUserData();
      const token = getAuthToken();
      let resellerId = undefined;

      if (token) {
        try {
          const payload = JSON.parse(atob(token.split('.')[1]));
          const role = payload.role || userData?.role;
          if (role === 'reseller' && userData?.id) {
            resellerId = userData.id;
          }
        } catch (err) {
          console.error("Error decoding token:", err);
        }
      }

      const result = await getMstSubscriptionPlans(resellerId);
      if (result.success) {
        const filteredPlans = (result.data || []).filter(
          (plan) => plan.is_active === true
        );
        setSubscriptionPlans(filteredPlans);
      }
    } catch (err) {
      console.error("Error fetching subscription plans:", err);
      setError("Failed to load subscription plans");
    } finally {
      setLoadingPlans(false);
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => {
      const next = { ...prev, [name]: value };
      if (name === "subscription_plan_id" && value && subscriptionPlans.length > 0) {
        const plan = subscriptionPlans.find((p) => p.id === value);
        if (plan != null && plan.amount != null) {
          next.payment_amount = String(plan.amount);
        }
      }
      return next;
    });
    setError("");
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (isSubmittingRef.current) return;
    setError("");
    setSuccess(false);

    if (!formData.payment_method) {
      setError("Please select a payment method");
      return;
    }

    if (formData.payment_method === "offline") {
      if (!formData.payment_reference_number || !formData.payment_amount || !formData.payment_date || !formData.call_forwarding_number) {
        setError("Please fill all required fields for offline payment");
        return;
      }
      const amount = parseFloat(formData.payment_amount);
      if (isNaN(amount) || amount <= 0) {
        setError("Payment amount must be a valid positive number");
        return;
      }
    } else if (formData.payment_method === "online") {
      if (!formData.subscription_plan_id) {
        setError("Please select a subscription plan");
        return;
      }
      if (!formData.call_forwarding_number || !formData.call_forwarding_number.trim()) {
        setError("Please enter Call Forwarding Number");
        return;
      }
    }

    isSubmittingRef.current = true;
    setLoading(true);

    try {
      const API_BASE_URL = getApiBaseUrl();
      const response = await fetch(`${API_BASE_URL}/customer/add-virtual-number`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${getAuthToken()}`,
        },
        body: JSON.stringify({
          customer_id: customer.id,
          ...formData,
        }),
      });

      const result = await response.json();

      if (result.success) {
        setSuccess(true);
        setTimeout(() => {
          window.dispatchEvent(new CustomEvent("wallet-should-refresh"));
        }, 300);
        setTimeout(() => {
          onSuccess();
          onClose();
        }, 1500);
      } else {
        setError(result.message || "Failed to add virtual number");
      }
    } catch (err) {
      console.error("Error adding virtual number:", err);
      setError(err.message || "An error occurred while adding virtual number");
    } finally {
      setLoading(false);
      isSubmittingRef.current = false;
    }
  };

  if (!isOpen) return null;

  return (
    <div className="modal show d-block" style={{ backgroundColor: 'rgba(0,0,0,0.5)' }} tabIndex="-1">
      <div className="modal-dialog modal-dialog-centered modal-lg">
        <div className="modal-content radius-12">
          <div className="modal-header border-bottom">
            <h5 className="modal-title text-md text-primary-light">Add Virtual Number</h5>
            <button
              type="button"
              className="btn-close"
              onClick={onClose}
              disabled={loading}
              aria-label="Close"
            />
          </div>
          <form onSubmit={handleSubmit}>
            <div className="modal-body p-24">
              <div className="mb-20">
                <p className="text-sm text-secondary-light mb-0">
                  Add virtual number for: <strong>{customer?.profile_name || customer?.email}</strong>
                </p>
              </div>

              {error && (
                <div className="alert alert-danger radius-8 mb-24 d-flex align-items-center" role="alert">
                  <Icon icon="material-symbols:error-outline" className="icon me-2 flex-shrink-0" />
                  {error}
                </div>
              )}

              {success && (
                <div className="alert alert-success radius-8 mb-24 d-flex align-items-center" role="alert">
                  <Icon icon="material-symbols:check-circle-outline" className="icon me-2 flex-shrink-0" />
                  {formData.payment_method === "online"
                    ? "Payment link sent to customer email!"
                    : "Virtual number added successfully!"}
                </div>
              )}

              <div className="mb-20">
                <label
                  htmlFor="payment_method"
                  className="form-label fw-semibold text-primary-light text-sm mb-8"
                >
                  Payment Method <span className="text-danger-600">*</span>
                </label>
                <select
                  className="form-select radius-8"
                  id="payment_method"
                  name="payment_method"
                  value={formData.payment_method}
                  onChange={handleChange}
                  required
                  disabled={loading}
                >
                  <option value="">Select Payment Method</option>
                  <option value="offline">Offline Payment</option>
                  <option value="online">Online Payment</option>
                </select>
              </div>

              {/* Offline Payment Fields */}
              {formData.payment_method === "offline" && (
                <>
                  <div className="mb-20">
                    <label
                      htmlFor="subscription_plan_id_offline"
                      className="form-label fw-semibold text-primary-light text-sm mb-8"
                    >
                      Subscription Plan
                    </label>
                    {loadingPlans ? (
                      <div className="text-center py-3">
                        <div className="spinner-border spinner-border-sm text-primary" role="status">
                          <span className="visually-hidden">Loading...</span>
                        </div>
                        <p className="text-sm text-muted mt-2">Loading plans...</p>
                      </div>
                    ) : subscriptionPlans.length === 0 ? (
                      <div className="alert alert-warning radius-8 d-flex align-items-center">
                        <Icon icon="material-symbols:warning-outline" className="icon me-2 flex-shrink-0" />
                        No active subscription plans found.
                      </div>
                    ) : (
                      <select
                        className="form-select radius-8"
                        id="subscription_plan_id_offline"
                        name="subscription_plan_id"
                        value={formData.subscription_plan_id}
                        onChange={handleChange}
                        disabled={loading}
                      >
                        <option value="">Select Subscription Plan</option>
                        {subscriptionPlans.map((plan) => (
                          <option key={plan.id} value={plan.id}>
                            {plan.plan_name} - ₹{Number(plan.amount).toFixed(2)} ({plan.duration_days} days)
                          </option>
                        ))}
                      </select>
                    )}
                  </div>

                  <div className="mb-20">
                    <label
                      htmlFor="payment_amount"
                      className="form-label fw-semibold text-primary-light text-sm mb-8"
                    >
                      Payment Amount (₹) <span className="text-danger-600">*</span>
                    </label>
                    <input
                      type="number"
                      step="0.01"
                      min="0"
                      className="form-control radius-8"
                      id="payment_amount"
                      name="payment_amount"
                      placeholder="Enter payment amount"
                      value={formData.payment_amount}
                      onChange={handleChange}
                      required
                      disabled={loading}
                    />
                    {/* <p className="text-muted text-sm mt-8 mb-0">
                      Your reseller price per number will be deducted from your wallet.
                    </p> */}
                  </div>

                  <div className="mb-20">
                    <label
                      htmlFor="payment_date"
                      className="form-label fw-semibold text-primary-light text-sm mb-8"
                    >
                      Payment Date <span className="text-danger-600">*</span>
                    </label>
                    <input
                      type="date"
                      className="form-control radius-8"
                      id="payment_date"
                      name="payment_date"
                      value={formData.payment_date}
                      onChange={handleChange}
                      required
                      disabled={loading}
                    />
                  </div>

                  <div className="mb-20">
                    <label
                      htmlFor="payment_reference_number"
                      className="form-label fw-semibold text-primary-light text-sm mb-8"
                    >
                      Payment Reference Number <span className="text-danger-600">*</span>
                    </label>
                    <input
                      type="text"
                      className="form-control radius-8"
                      id="payment_reference_number"
                      name="payment_reference_number"
                      placeholder="Enter payment reference number"
                      value={formData.payment_reference_number}
                      onChange={handleChange}
                      required
                      disabled={loading}
                    />
                  </div>

                  <div className="mb-20">
                    <label
                      htmlFor="call_forwarding_number_offline"
                      className="form-label fw-semibold text-primary-light text-sm mb-8"
                    >
                      Call Forwarding Number <span className="text-danger-600">*</span>
                    </label>
                    <input
                      type="tel"
                      className="form-control radius-8"
                      id="call_forwarding_number_offline"
                      name="call_forwarding_number"
                      placeholder="Enter call forwarding number"
                      value={formData.call_forwarding_number}
                      onChange={handleChange}
                      required
                      disabled={loading}
                    />
                    <small className="text-muted d-block mt-1">
                      Phone number where calls to the virtual number will be forwarded
                    </small>
                  </div>
                </>
              )}

              {/* Online Payment Fields */}
              {formData.payment_method === "online" && (
                <>
                  <div className="mb-20">
                    <label
                      htmlFor="subscription_plan_id_online"
                      className="form-label fw-semibold text-primary-light text-sm mb-8"
                    >
                      Subscription Plan <span className="text-danger-600">*</span>
                    </label>
                    {loadingPlans ? (
                      <div className="text-center py-3">
                        <div className="spinner-border spinner-border-sm text-primary" role="status">
                          <span className="visually-hidden">Loading...</span>
                        </div>
                        <p className="text-sm text-muted mt-2">Loading plans...</p>
                      </div>
                    ) : subscriptionPlans.length === 0 ? (
                      <div className="alert alert-warning radius-8 d-flex align-items-center">
                        <Icon icon="material-symbols:warning-outline" className="icon me-2 flex-shrink-0" />
                        No active subscription plans found. Please create a subscription plan first.
                      </div>
                    ) : (
                      <select
                        className="form-select radius-8"
                        id="subscription_plan_id_online"
                        name="subscription_plan_id"
                        value={formData.subscription_plan_id}
                        onChange={handleChange}
                        required
                        disabled={loading}
                      >
                        <option value="">Select Subscription Plan</option>
                        {subscriptionPlans.map((plan) => (
                          <option key={plan.id} value={plan.id}>
                            {plan.plan_name} - ₹{Number(plan.amount).toFixed(2)} ({plan.duration_days} days)
                          </option>
                        ))}
                      </select>
                    )}
                  </div>

                  <div className="mb-20">
                    <label
                      htmlFor="call_forwarding_number_online"
                      className="form-label fw-semibold text-primary-light text-sm mb-8"
                    >
                      Call Forwarding Number <span className="text-danger-600">*</span>
                    </label>
                    <input
                      type="tel"
                      className="form-control radius-8"
                      id="call_forwarding_number_online"
                      name="call_forwarding_number"
                      placeholder="Enter call forwarding number"
                      value={formData.call_forwarding_number}
                      onChange={handleChange}
                      required
                      disabled={loading}
                    />
                    <small className="text-muted d-block mt-1">
                      Phone number where calls to the virtual number will be forwarded
                    </small>
                  </div>
                </>
              )}
            </div>
            <div className="modal-footer border-top">
              <button
                type="button"
                className="btn btn-secondary radius-8"
                onClick={onClose}
                disabled={loading}
              >
                Cancel
              </button>
              <button
                type="submit"
                className="btn btn-primary radius-8 d-flex align-items-center"
                disabled={loading || !formData.payment_method || (formData.payment_method === "online" && subscriptionPlans.length === 0)}
              >
                {loading ? (
                  <>
                    <span className="spinner-border spinner-border-sm me-2 flex-shrink-0" role="status" aria-hidden="true"></span>
                    {formData.payment_method === "online" ? "Sending..." : "Adding..."}
                  </>
                ) : (
                  <>
                    <Icon icon="ic:baseline-plus" className="icon me-2 flex-shrink-0" />
                    {formData.payment_method === "online" ? "Send Payment Link" : "Add Virtual Number"}
                  </>
                )}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default AddVirtualNumberModal;
