import { Icon } from "@iconify/react/dist/iconify.js";
import { Link } from "react-router-dom";
import { useState, useEffect } from "react";
import { getMstCustomersByReseller, getAllMstCustomers } from "@/hasura/mutations/customer";
import { getUserData, getAuthToken } from "@/utils/auth";
import { formatDateIST } from "@/utils/dateUtils";
import PermissionGuard from "@/components/PermissionGuard";
import { useResellerValidityGate } from "@/contexts/ResellerValidityGateContext";

const CustomerListLayer = () => {
  const [customers, setCustomers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState("all"); // Show all customers by default
  const [isAdmin, setIsAdmin] = useState(false);
  const [isReseller, setIsReseller] = useState(false);
  const [isSuperAdmin, setIsSuperAdmin] = useState(false);
  const { loading: validityLoading, blocked: validityBlocked, reason: validityReason } =
    useResellerValidityGate();
  const resellerViewDisabled =
    isReseller && !validityLoading && validityBlocked;

  useEffect(() => {
    // Check if user is admin or reseller
    const token = getAuthToken();
    const userData = getUserData();

    if (token) {
      try {
        const payload = JSON.parse(atob(token.split(".")[1]));
        const role = payload.role || userData?.role;
        const adminStatus = role === "admin" || role === "super_admin";
        const resellerStatus = role === "reseller";
        setIsAdmin(adminStatus);
        setIsReseller(resellerStatus);
        setIsSuperAdmin(role === "super_admin");
        
        // Fetch customers after role is determined
        fetchCustomers(adminStatus, resellerStatus);
      } catch (err) {
        console.error("Error decoding token:", err);
      }
    }
  }, []);

  const fetchCustomers = async (adminStatus = isAdmin, resellerStatus = isReseller) => {
    setLoading(true);
    setError("");
    try {
      let result;

      // If user is admin/super_admin, fetch all customers
      if (adminStatus) {
        result = await getAllMstCustomers();
      } else {
        // For resellers, fetch only their customers
        const userData = getUserData();
        if (!userData || !userData.id) {
          setError("Unable to determine reseller ID. Please log in again.");
          setCustomers([]);
          setLoading(false);
          return;
        }
        result = await getMstCustomersByReseller(userData.id);
      }

      if (result && result.success) {
        // Always set an array, even if data is undefined or null
        setCustomers(Array.isArray(result.data) ? result.data : []);
      } else {
        // If result is falsy or success is false, set empty array
        setCustomers([]);
        if (result && result.message) {
          setError(result.message);
        } else {
          setError("Failed to load customers");
        }
      }
    } catch (err) {
      console.error("Error fetching customers:", err);
      setError("An error occurred while loading customers");
      setCustomers([]); // Ensure empty array on error
    } finally {
      setLoading(false);
    }
  };

  // Filter customers based on search, status, exclude approved, and require signatureImage
  // Consider both approval and status - approved/active customers should not show in New Customers
  const filteredCustomers = customers.filter((customer) => {
    const isApproved =
      customer.approval === "approved" ||
      customer.status === "approved" ||
      customer.status === "active";
    const notApproved = !isApproved;
    const hasSignature = !!customer.signatureImage?.trim();

    const matchesSearch =
      searchTerm === "" ||
      customer.profile_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      customer.email?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      customer.phone?.includes(searchTerm) ||
      customer.business_email?.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesStatus =
      statusFilter === "all" || customer.status === statusFilter;

    return notApproved && hasSignature && matchesSearch && matchesStatus;
  });

  const formatDate = formatDateIST;

  const getStatusBadge = (status) => {
    const statusConfig = {
      pending: {
        class: "bg-warning-focus text-warning-600 border-warning-main",
        text: "Pending",
      },
      pending_payment: {
        class: "bg-info-focus text-info-600 border-info-main",
        text: "Pending Payment",
      },
      approved: {
        class: "bg-primary-focus text-primary-600 border-primary-main",
        text: "Approved",
      },
      active: {
        class: "bg-success-focus text-success-600 border-success-main",
        text: "Active",
      },
      rejected: {
        class: "bg-danger-focus text-danger-600 border-danger-main",
        text: "Rejected",
      },
      suspended: {
        class: "bg-secondary-focus text-secondary-600 border-secondary-main",
        text: "Suspended",
      },
    };

    const config = statusConfig[status] || statusConfig.pending;
    return (
      <span
        className={`${config.class} border px-24 py-4 radius-4 fw-medium text-sm`}
      >
        {config.text}
      </span>
    );
  };

  const getKycStatusBadge = (kycStatus) => {
    const statusConfig = {
      pending: {
        class: "bg-warning-focus text-warning-600 border-warning-main",
        text: "Pending",
      },
      verified: {
        class: "bg-success-focus text-success-600 border-success-main",
        text: "Verified",
      },
      rejected: {
        class: "bg-danger-focus text-danger-600 border-danger-main",
        text: "Rejected",
      },
    };

    const config = statusConfig[kycStatus] || statusConfig.pending;
    return (
      <span
        className={`${config.class} border px-24 py-4 radius-4 fw-medium text-sm`}
      >
        {config.text}
      </span>
    );
  };

  return (
    <div className="card h-100 p-0 radius-12">
      <div className="card-header border-bottom bg-base py-16 px-24 d-flex align-items-center flex-wrap gap-3 justify-content-between">
        <div className="d-flex align-items-center flex-wrap gap-3">
          <form className="navbar-search">
            <input
              type="text"
              className="bg-base h-40-px w-auto"
              name="search"
              placeholder="Search by name, email, or phone"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
            <Icon icon="ion:search-outline" className="icon" />
          </form>
          <select
            className="form-select form-select-sm w-auto ps-12 py-6 radius-12 h-40-px"
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
          >
            <option value="all">All Status</option>
            <option value="pending">Pending</option>
            <option value="pending_payment">Pending Payment</option>
            <option value="rejected">Rejected</option>
            <option value="suspended">Suspended</option>
          </select>
        </div>

        {isSuperAdmin && (
          <Link
            to="/add-customer"
            className="btn btn-primary text-sm btn-sm px-12 py-12 radius-8 d-flex align-items-center gap-2"
          >
            <Icon
              icon="ic:baseline-plus"
              className="icon text-xl line-height-1"
            />
            Add New Customer
          </Link>
        )}
      </div>
      <div className="card-body p-24">
        {error && (
          <div className="alert alert-danger radius-8 mb-24" role="alert">
            <Icon icon="material-symbols:error-outline" className="icon me-2" />
            {error}
          </div>
        )}

        {loading ? (
          <div className="text-center py-40">
            <div className="spinner-border text-primary" role="status">
              <span className="visually-hidden">Loading...</span>
            </div>
            <p className="text-muted mt-3">Loading customers...</p>
          </div>
        ) : filteredCustomers.length === 0 ? (
          <div className="text-center py-40">
            <Icon
              icon="mdi:account-off"
              className="icon text-6xl text-muted mb-3"
            />
            <p className="text-muted">No customers found</p>
          </div>
        ) : (
          <>
            <div className="table-responsive scroll-sm">
              <table className="table bordered-table sm-table mb-0">
                <thead>
                  <tr>
                    <th scope="col">S.L</th>
                    <th scope="col">Customer Name</th>
                    <th scope="col">Phone</th>
                    <th scope="col">Date</th>
                    {!isReseller && <th scope="col">Reseller</th>}
                    <th scope="col">Email</th>
                    {/* <th scope="col">Business Email</th> */}
                    <th scope="col" className="text-center">
                      Status
                    </th>
                    {/* <th scope="col" className="text-center">
                      KYC Status
                    </th> */}
                    <th scope="col" className="text-center">
                      Action
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {filteredCustomers.map((customer, index) => (
                    <tr key={customer.id}>
                      <td>{index + 1}</td>
                      <td>
                        <span className="text-md mb-0 fw-normal text-secondary-light">
                          {customer.profile_name || customer.business_name || customer.pan_full_name || customer.email || "-"}
                        </span>
                      </td>
                      <td>
                        <span className="text-md mb-0 fw-normal text-secondary-light">
                          {customer.phone || "-"}
                        </span>
                      </td>
                      <td>{formatDate(customer.created_at)}</td>
                      {!isReseller && (
                        <td>
                          <span className="text-md mb-0 fw-normal text-secondary-light">
                            {customer.mst_reseller?.brand_name || customer.mst_reseller?.business_name ||
                             (customer.mst_reseller?.first_name && customer.mst_reseller?.last_name
                               ? `${customer.mst_reseller.first_name} ${customer.mst_reseller.last_name}`
                               : customer.mst_reseller?.email || "-")}
                          </span>
                        </td>
                      )}
                      <td>
                        <span className="text-md mb-0 fw-normal text-secondary-light">
                          {customer.email || "-"}
                        </span>
                      </td>
                      {/* <td>
                        <span className="text-md mb-0 fw-normal text-secondary-light">
                          {customer.business_email || "-"}
                        </span>
                      </td> */}
                      <td className="text-center">
                        {getStatusBadge(customer.status)}
                      </td>
                      {/* <td className="text-center">
                        {getKycStatusBadge(customer.kyc_status)}
                      </td> */}
                      <td className="text-center">
                        <div className="d-flex align-items-center gap-10 justify-content-center flex-wrap">
                          {resellerViewDisabled ? (
                            <span
                              className="d-inline-block"
                              title={validityReason}
                              style={{ cursor: "not-allowed" }}
                            >
                              <span
                                className="bg-info-focus text-info-600 fw-medium w-40-px h-40-px d-flex justify-content-center align-items-center rounded-circle opacity-50 pointer-events-none"
                                aria-disabled="true"
                              >
                                <Icon
                                  icon="majesticons:eye-line"
                                  className="icon text-xl"
                                />
                              </span>
                            </span>
                          ) : (
                            <Link
                              to={`/view-customer/${customer.id}`}
                              className="bg-info-focus bg-hover-info-200 text-info-600 fw-medium w-40-px h-40-px d-flex justify-content-center align-items-center rounded-circle"
                              title="View KYC Details"
                            >
                              <Icon
                                icon="majesticons:eye-line"
                                className="icon text-xl"
                              />
                            </Link>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            <div className="d-flex align-items-center justify-content-between flex-wrap gap-2 mt-24">
              <span>
                Showing {filteredCustomers.length} of {customers.length}{" "}
                customer(s)
              </span>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default CustomerListLayer;
